<?php require_once __DIR__.'/bootstrap.php'; $u=require_login();$rows=db()->query("SELECT p.*,COUNT(s.id) submissions FROM projects p LEFT JOIN submissions s ON s.project_id=p.id GROUP BY p.id ORDER BY p.project_code")->fetchAll(); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Projects | ISLANDS</title><link rel="stylesheet" href="assets/app.css"></head><body><div class="app-shell"><?php include __DIR__.'/partials/sidebar.php'; ?><main class="main"><header class="topbar"><div><div class="eyebrow">PROGRAMME STRUCTURE</div><h1>Child projects</h1><p class="muted">ISLANDS programme project portfolio.</p></div></header><section class="project-grid"><?php foreach($rows as $p): ?><article class="project-card"><div class="project-code"><?=e($p['project_code'])?></div><div class="region"><?=e($p['region'])?></div><h3><?=e($p['project_name'])?></h3><p><?=e($p['countries'])?></p><div class="project-foot"><span><?=e((string)$p['submissions'])?> submissions</span><a href="submissions.php?q=<?=urlencode($p['project_code'])?>">View →</a></div></article><?php endforeach; ?></section></main></div></body></html>
